/**
 * BERT WordPiece tokenizer, reading a Hugging Face `tokenizer.json`.
 *
 * Follows the reference `BertNormalizer` + `BertPreTokenizer` + WordPiece steps
 * exactly, because a model only produces meaningful vectors from the token ids
 * it was trained on. `wordpiece-tokenizer.spec.ts` pins the output against ids
 * generated by the reference `tokenizers` library.
 */

interface TokenizerJson {
  model?: {
    type?: string;
    vocab?: Record<string, number>;
    unk_token?: string;
    continuing_subword_prefix?: string;
    max_input_chars_per_word?: number;
  };
  normalizer?: { type?: string; lowercase?: boolean };
}

/** Enough source text for any token budget; a token rarely spans more characters. */
const CHARS_PER_TOKEN_BUDGET = 16;

const PUNCTUATION = /\p{P}/u;
const COMBINING_MARK = /\p{Mn}/gu;
const CONTROL = /\p{C}/u;
const WHITESPACE = /\s/u;

function isCjk(codePoint: number): boolean {
  return (codePoint >= 0x4e00 && codePoint <= 0x9fff)
    || (codePoint >= 0x3400 && codePoint <= 0x4dbf)
    || (codePoint >= 0x20000 && codePoint <= 0x2a6df)
    || (codePoint >= 0x2a700 && codePoint <= 0x2b73f)
    || (codePoint >= 0x2b740 && codePoint <= 0x2b81f)
    || (codePoint >= 0x2b820 && codePoint <= 0x2ceaf)
    || (codePoint >= 0xf900 && codePoint <= 0xfaff)
    || (codePoint >= 0x2f800 && codePoint <= 0x2fa1f);
}

/** ASCII symbols count as punctuation here even though Unicode files some elsewhere. */
function isPunctuation(char: string, codePoint: number): boolean {
  return (codePoint >= 33 && codePoint <= 47)
    || (codePoint >= 58 && codePoint <= 64)
    || (codePoint >= 91 && codePoint <= 96)
    || (codePoint >= 123 && codePoint <= 126)
    || PUNCTUATION.test(char);
}

export class WordPieceTokenizer {
  private readonly clsId: number;
  private readonly sepId: number;
  private readonly unkId: number;
  private readonly prefix: string;
  private readonly maxWordChars: number;

  private constructor(private readonly vocab: Map<string, number>, model: NonNullable<TokenizerJson['model']>) {
    this.clsId = this.requireId('[CLS]');
    this.sepId = this.requireId('[SEP]');
    this.unkId = this.requireId(model.unk_token ?? '[UNK]');
    this.prefix = model.continuing_subword_prefix ?? '##';
    this.maxWordChars = model.max_input_chars_per_word ?? 100;
  }

  static fromJson(json: unknown): WordPieceTokenizer {
    const parsed = json as TokenizerJson;
    if (parsed.model?.type !== 'WordPiece' || !parsed.model.vocab) {
      throw new Error('Embedding tokenizer is not a WordPiece model');
    }
    if (parsed.normalizer?.type !== 'BertNormalizer' || parsed.normalizer.lowercase !== true) {
      throw new Error('Embedding tokenizer does not use the lower-casing BERT normalizer');
    }
    return new WordPieceTokenizer(new Map(Object.entries(parsed.model.vocab)), parsed.model);
  }

  /** Token ids for a text, wrapped in `[CLS]` and `[SEP]`, at most `maxTokens` long. */
  encode(text: string, maxTokens: number): number[] {
    const budget = maxTokens - 2;
    const ids: number[] = [this.clsId];
    for (const word of this.splitWords(this.normalize(text.slice(0, maxTokens * CHARS_PER_TOKEN_BUDGET)))) {
      for (const id of this.wordPieces(word)) {
        if (ids.length > budget) {
          ids.push(this.sepId);
          return ids;
        }
        ids.push(id);
      }
    }
    ids.push(this.sepId);
    return ids;
  }

  private requireId(token: string): number {
    const id = this.vocab.get(token);
    if (id === undefined) {
      throw new Error(`Embedding tokenizer vocabulary has no ${token}`);
    }
    return id;
  }

  /** Clean, isolate CJK characters, strip accents and lower-case. */
  private normalize(text: string): string {
    let cleaned = '';
    for (const char of text) {
      const codePoint = char.codePointAt(0) ?? 0;
      if (WHITESPACE.test(char)) {
        cleaned += ' ';
      } else if (codePoint === 0 || codePoint === 0xfffd || CONTROL.test(char)) {
        continue;
      } else if (isCjk(codePoint)) {
        cleaned += ` ${char} `;
      } else {
        cleaned += char;
      }
    }
    return cleaned.normalize('NFD').replace(COMBINING_MARK, '').toLowerCase();
  }

  /** Split on whitespace, with each punctuation character becoming its own word. */
  private splitWords(text: string): string[] {
    const words: string[] = [];
    let current = '';
    for (const char of text) {
      const codePoint = char.codePointAt(0) ?? 0;
      if (char === ' ') {
        if (current) words.push(current);
        current = '';
      } else if (isPunctuation(char, codePoint)) {
        if (current) words.push(current);
        current = '';
        words.push(char);
      } else {
        current += char;
      }
    }
    if (current) words.push(current);
    return words;
  }

  /** Greedy longest-match-first; a word with any unknown piece becomes `[UNK]`. */
  private wordPieces(word: string): number[] {
    const chars = Array.from(word);
    if (chars.length > this.maxWordChars) return [this.unkId];

    const pieces: number[] = [];
    let start = 0;
    while (start < chars.length) {
      let end = chars.length;
      let pieceId: number | undefined;
      while (start < end) {
        const candidate = chars.slice(start, end).join('');
        pieceId = this.vocab.get(start === 0 ? candidate : `${this.prefix}${candidate}`);
        if (pieceId !== undefined) break;
        end -= 1;
      }
      if (pieceId === undefined) return [this.unkId];
      pieces.push(pieceId);
      start = end;
    }
    return pieces;
  }
}
